export function translateUI(text) {
 if(language!=='ru')return text;
 const value=String(text), trimmed=value.trim();
 let translated=RU[trimmed];
 if(translated===undefined){
  const patterns=[
   [/^Chart units: (.*)\.$/,m=>`Единицы на графике: ${m[1]}.`],
   [/^(\d+) record$/,m=>`Записей: ${m[1]}`],
   [/^(\d[\d,]*) records in (.*?)( found)?$/,m=>`Записей: ${m[1]} · ${RU[m[2]]||m[2]}`],
   [/^All records (\d+)$/,m=>`Все записи ${m[1]}`],
   [/^Saved (\d+)$/,m=>`Избранное ${m[1]}`],
   [/^(\d[\d,]*) records imported$/,m=>`Импортировано записей: ${m[1]}`],
   [/^(\d[\d,]*) records$/,m=>`Записей: ${m[1]}`],
   [/^(\d[\d,]*) records found$/,m=>`Найдено записей: ${m[1]}`],
   [/^(\d+) medication and supplement histories$/,m=>`Историй препаратов и добавок: ${m[1]}`],
   [/^Read source (\d+): (.*)$/s,m=>`Открыть источник ${m[1]}: ${m[2]}`],
   [/^Save: (.*)$/s,m=>`В избранное: ${m[1]}`],[/^Unsave: (.*)$/s,m=>`Убрать из избранного: ${m[1]}`],
   [/^Posted (.*)$/s,m=>`Опубликовано ${m[1]}`],
   [/^Archive snapshot · (.*)$/s,m=>`Снимок архива · ${m[1]}`],
   [/^Original note #(\d+) · posted (.*)$/s,m=>`Исходная запись №${m[1]} · опубликована ${m[2]}`],
   [/^(\d+) document references · includes the PDF extracted from the original ZIP$/,m=>`Вложений: ${m[1]}, включая PDF из исходного ZIP`],
   [/^(\d+) image originals, (\d+) original PDFs, and one ZIP with an additional PDF\. Text from (\d+) PDFs is searchable\. Scanned images are available to view; their handwriting has not been automatically transcribed\.$/,m=>`${m[1]} исходных изображений, ${m[2]} PDF и один ZIP с дополнительным PDF. По тексту ${m[3]} PDF работает поиск. Сканы доступны для просмотра; рукописный текст автоматически не расшифрован.`],
   [/^Original Telegram message #(\d+) · (.*?) · posted (.*?)\. (.*)$/s,m=>`Исходное сообщение Telegram №${m[1]} · ${m[2]} · опубликовано ${m[3]}. ${RU[m[4]]||m[4]}`],
   [/^Preview: (.*)$/s,m=>`Предпросмотр: ${m[1]}`],
   [/^Show more \((\d+) remaining\)$/,m=>`Показать ещё (осталось ${m[1]})`],
   [/^(PDF|JPG|JPEG|PNG|ZIP) · (Text searchable|Original document)( · password protected)?$/,m=>`${m[1]} · ${m[2]==='Text searchable'?'Поиск по тексту':'Исходный документ'}${m[3]?' · с паролем':''}`],
   [/^(\d+) measurements$/,m=>`Измерений: ${m[1]}`],[/^(\d+) days ago$/,m=>`${m[1]} дн. назад`]
  ];
  for(const [pattern,replace] of patterns){const match=trimmed.match(pattern);if(match){translated=replace(match);break;}}
 }
 if(translated===undefined)return value;
 return value.replace(trimmed,translated);
}

export function configureLanguage(snapshot,onChange) {
 Object.assign(RU,snapshot.translationsRu||{});
 const texts=new WeakMap(), attributes=new WeakMap();
 const root=document.body;
 const excluded=node=>node.parentElement?.closest('script,style,.record-body,[data-no-translate]');
 const apply=()=>{
  document.documentElement.lang=language;
  document.title=language==='ru'?'Здоровье Айжан · Личный медицинский архив':'Aijan’s Health Records · Personal medical archive';
  const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
  let node;
  while((node=walker.nextNode())){
   if(excluded(node)||!node.nodeValue?.trim())continue;
   const previous=texts.get(node),current=node.nodeValue;
   const original=previous&&current===previous.last?previous.original:current;
   const translated=translateUI(original);
   texts.set(node,{original,last:translated});
   if(current!==translated)node.nodeValue=translated;
  }
  root.querySelectorAll('[aria-label],[placeholder],[title]').forEach(element=>{
   if(element.closest('.record-body,[data-no-translate]'))return;
   const previous=attributes.get(element)||{};
   for(const name of ['aria-label','placeholder','title']){
    const current=element.getAttribute(name);if(current===null)continue;
    const known=previous[name],original=known&&current===known.last?known.original:current;
    const translated=translateUI(original);previous[name]={original,last:translated};
    if(current!==translated)element.setAttribute(name,translated);
   }
   attributes.set(element,previous);
  });
  const select=document.getElementById('language-select');if(select)select.value=language;
 };
 const observe=()=>observer.observe(root,{childList:true,subtree:true,characterData:true});
 const observer=new MutationObserver(()=>{observer.disconnect();apply();observe();});
 document.getElementById('language-select')?.addEventListener('change',event=>{
  language=event.target.value==='en'?'en':'ru';
  try{localStorage.setItem('health-records-language',language);}catch{}
  onChange();observer.disconnect();apply();observe();
 });
 apply();observe();
 return {apply,register:translations=>Object.assign(RU,translations||{})};
}
